// Asset loading for the web port. Assets are generated by tools/export_web_assets.py
// from the original files in game files/.

async function fetchJson(url) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`fetch ${url}: ${r.status}`);
  return r.json();
}

function loadImage(url) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`img ${url}`));
    img.src = url;
  });
}

export async function loadAssets(base = 'assets/') {
  const [palette, sprites, areas, sys, world, mechanics, startup] = await Promise.all([
    fetchJson(base + 'palette.json'),
    fetchJson(base + 'sprites.json'),
    fetchJson(base + 'areas.json'),
    fetchJson(base + 'sys.json'),
    fetchJson(base + 'world.json'),
    fetchJson(base + 'mechanics.json'),
    fetchJson(base + 'startup.json'),
  ]);
  const sysImgs = {};
  for (const [name, info] of Object.entries(sys)) {
    sysImgs[name] = { ...info, img: await loadImage(info.sheet) };
  }

  const hud = await fetchJson(base + 'hud.json');
  const hudImgs = {};
  for (const [key, info] of Object.entries(hud)) {
    if (info && info.img) hudImgs[key] = { ...info, img: await loadImage(base + info.img.replace('assets/', '')) };
    else if (key === 'items') {
      hudImgs.items = {};
      for (const [iname, iinfo] of Object.entries(info)) {
        hudImgs.items[iname] = { ...iinfo, img: await loadImage(base + iinfo.img.replace('assets/', '')) };
      }
    }
  }

  const tiles = {};
  const levels = {};
  for (const entry of areas.entries) {
    const area = entry.area.toUpperCase();
    const [tileInfo, level] = await Promise.all([
      fetchJson(`${base}tiles/${area}.json`),
      fetchJson(`${base}levels/${area}.json`),
    ]);
    tileInfo.img = await loadImage(tileInfo.sheet);  // sheet path already includes assets/
    tiles[area] = tileInfo;
    levels[area] = level;
  }

  const spriteImgs = {};
  for (const [name, info] of Object.entries(sprites)) {
    spriteImgs[name] = { ...info, img: await loadImage(info.sheet) };
  }

  return { palette, sprites: spriteImgs, areas, world, mechanics, startup, tiles, levels,
    sys: sysImgs, hud, hudImgs };
}
